     * @throws GqlException
     */
    public function testLowerMapsNothingWhenThereIsNothingToMap(): void
    {
        self::assertSame(DatumKind::Null, TextFunctions::lower(new NullDatum())->kind());
    }

    /**
     * @throws GqlException
     */
